import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.D9E58p8B.js";const u=JSON.parse('{"title":"With an agent","description":"","frontmatter":{"title":"With an agent"},"headers":[],"relativePath":"en/agent/index.md","filePath":"en/agent/index.md"}'),i={name:"en/agent/index.md"};function r(s,e,h,d,l,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="with-an-agent" tabindex="-1">With an agent <a class="header-anchor" href="#with-an-agent" aria-label="Permalink to &quot;With an agent&quot;">​</a></h1><p>Your AI agent uses Daimon through its MCP tools: it looks at the screen, reads the interface, acts on your behalf and shows you what it is doing. You decide, the agent executes, and the ceiling you set bounds everything it can do.</p><p>You talk to your agent in natural language. Each page of this guide starts from what you ask it, then says what it does, what you get, and what happens when a call is refused.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><p>Daimon does not target one particular agent: any MCP client that can launch a server over stdio can use it. Agents backed by frontier models are the most likely to chain perception and action reliably. The list of clients Daimon knows how to configure is in <a href="/Daimon/en/guide/clients-mcp.html">AI clients</a>.</p><h2 id="working-at-your-best" tabindex="-1">Working at your best <a class="header-anchor" href="#working-at-your-best" aria-label="Permalink to &quot;Working at your best&quot;">​</a></h2><p>Unlike a tool tied to a project, Daimon has no working folder: it acts on <strong>your machine</strong>, wherever the agent&#39;s session is open. What matters:</p><ul><li><strong>Daimon is registered in your agent</strong> and the agent has been restarted since (see below);</li><li><strong>the system permissions are granted</strong>: <a href="/Daimon/en/guide/autorisations.html">Permissions</a>;</li><li><strong>the ceiling matches the task</strong>: at L0 (the default setting), the agent can look but not act. See <a href="/Daimon/en/agent/agir.html">Acting</a>;</li><li><strong>the Daimon panel is within reach</strong>, and <strong>Présence à l&#39;écran</strong> (On-screen presence) is turned on if you want to see what the agent is doing: see <a href="/Daimon/en/agent/montrer.html">Showing what is happening</a>.</li></ul><p>Then talk to it: &quot;Check that Daimon is ready&quot; or &quot;Look at my screen and tell me which window is in the foreground&quot;.</p><h2 id="connecting-an-agent" tabindex="-1">Connecting an agent <a class="header-anchor" href="#connecting-an-agent" aria-label="Permalink to &quot;Connecting an agent&quot;">​</a></h2><p>Three routes, which do the same job, detailed in <a href="/Daimon/en/guide/clients-mcp.html">AI clients</a>:</p><ul><li>the setup flow, then the panel, with one switch per client;</li><li>a terminal: <code>Daimon install</code> registers Daimon in every detected client;</li><li>for an unknown client, a stdio declaration whose command is the Daimon binary and whose argument is <code>serve</code>.</li></ul><p>After registering, <strong>restart your agent</strong> so that it sees the tools.</p><h2 id="you-stay-in-control" tabindex="-1">You stay in control <a class="header-anchor" href="#you-stay-in-control" aria-label="Permalink to &quot;You stay in control&quot;">​</a></h2><ul><li><strong>The ceiling.</strong> Each Mains (Hands) action has a level (L1 to L4). The agent can read the ceiling with <code>main_ceiling</code>, but <strong>never raise it</strong>.</li><li><strong>Confirmation.</strong> Up to L3, an action that Daimon judges irreversible stops on a confirmation dialog, which declines by itself after 30 seconds.</li><li><strong>L4 is your decision.</strong> It requires your explicit consent, from the panel or the terminal. No tool lets the agent engage it.</li><li><strong>Your exclusions.</strong> The applications and areas you protect are censored or refused: <a href="/Daimon/en/guide/plafond-et-exclusions.html">Ceiling and exclusions</a>.</li><li><strong>The audit.</strong> Every action is logged with the intent the agent declared.</li></ul><h2 id="when-a-call-is-refused" tabindex="-1">When a call is refused <a class="header-anchor" href="#when-a-call-is-refused" aria-label="Permalink to &quot;When a call is refused&quot;">​</a></h2><p>The refusal always says why, in a form your agent understands directly:</p><table tabindex="0"><thead><tr><th>Form</th><th>Meaning</th></tr></thead><tbody><tr><td><code>{&quot;status&quot;: &quot;refused&quot;, &quot;reason&quot;: &quot;…&quot;}</code></td><td>A Mains action is refused: ceiling, guard, confirmation not obtained</td></tr><tr><td><code>{&quot;status&quot;: &quot;error&quot;, &quot;reason&quot;: &quot;…&quot;}</code></td><td>A Mains action failed to run</td></tr><tr><td><code>{&quot;error&quot;: &quot;&lt;code&gt;&quot;, &quot;message&quot;: &quot;…&quot;}</code></td><td>A preparation or perception error: invalid argument, missing permission, protected application</td></tr></tbody></table><p>Each journey page lists the actual refusals of its tools. When in doubt, the agent calls <a href="/Daimon/en/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a>.</p><h2 id="the-journeys" tabindex="-1">The journeys <a class="header-anchor" href="#the-journeys" aria-label="Permalink to &quot;The journeys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>For</th></tr></thead><tbody><tr><td><a href="/Daimon/en/agent/demarrer.html">Getting started</a></td><td>Check that Daimon is ready before the first task</td></tr><tr><td><a href="/Daimon/en/agent/regarder.html">Looking at the screen</a></td><td>Capture a screen, locate a text, convert coordinates</td></tr><tr><td><a href="/Daimon/en/agent/lire-interface.html">Reading an interface</a></td><td>Get a window&#39;s elements without going through the image</td></tr><tr><td><a href="/Daimon/en/agent/agir.html">Acting</a></td><td>Click, type, press, drag, under the ceiling you set</td></tr><tr><td><a href="/Daimon/en/agent/montrer.html">Showing what is happening</a></td><td>See on screen what the agent is doing</td></tr><tr><td><a href="/Daimon/en/agent/deleguer.html">Delegating to a sub-agent</a></td><td>Hand a sequence of actions to another agent</td></tr><tr><td><a href="/Daimon/en/agent/diagnostiquer.html">When it doesn&#39;t work</a></td><td>Find the cause before concluding something is broken</td></tr></tbody></table><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><p>Every tool, its parameters and its level: <a href="/Daimon/en/reference/">Tool reference</a>.</p>',23)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
